import test from 'node:test';import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {World} from '../world.js';import {PHYSICAL_LORE} from '../physical-lore-content.js';
import {physicalBindings,physicalState,physicalObjects,interactPhysical,carryPhysical,dropPhysical,tickPhysical} from '../physical-lore.js';
import {availablePoints} from '../skill-grid-model.js';
import {findPath} from '../navigation.js';
const data=JSON.parse(readFileSync(new URL('../world.json',import.meta.url)));
function setup(){const w=new World(data);w.state.story.firstCore=true;w.state.chapter=24;w.state.mode='field';return w;}
function site(w,id,role){return physicalBindings(w).find(o=>o.physicalId===id&&o.physicalRole===role);}
function act(w,o){w.state.scene=o.physicalLocation;w.state.x=o.xy[0]+.5;w.state.y=o.xy[1]+.5;w.state.mode='field';w.interact(o);}
function collect(w,e){act(w,site(w,e.id,'source'));assert.equal(w.state.physicalLore.held,e.id);act(w,site(w,e.id,'device'));}
function solve(w,e){collect(w,e);if(e.mode==='turn')for(let n=0;n<e.orientation;n++)act(w,site(w,e.id,'device'));if(e.mode==='pump')for(let n=0;n<3;n++)act(w,site(w,e.id,'device'));if(e.mode==='grow'||e.mode==='listen'){for(let n=0;n<42;n++)tickPhysical(w,.1);if(e.mode==='listen')act(w,site(w,e.id,'device'));}assert.ok(w.state.physicalLore.completed.includes(e.id));}
test('24 artifact chains have 72 distinct reachable placements, without changing a floor or authored action',()=>{const w=setup(),bindings=physicalBindings(w);assert.equal(bindings.length,72);for(const scene of w.data.scenes){const all=bindings.filter(o=>o.physicalLocation===scene.location);for(const o of all){assert.equal(scene.floor[o.xy[1]][o.xy[0]],'.');assert.ok(findPath(scene,scene.arrive,o.xy).length);assert.ok(![...scene.doors,...scene.objects].some(v=>v.xy&&Math.hypot(v.xy[0]-o.xy[0],v.xy[1]-o.xy[1])<2.15));}assert.equal(new Set(all.map(o=>o.xy.join(','))).size,all.length);}for(const e of PHYSICAL_LORE){const target=site(w,e.id,'device'),reward=site(w,e.id,'reward');assert.ok(Math.hypot(target.xy[0]-reward.xy[0],target.xy[1]-reward.xy[1])<=6);}});
test('pickup, cross-room carry, drop, resume and retrieve preserve one physical copy',()=>{const w=setup(),e=PHYSICAL_LORE[0];act(w,site(w,e.id,'source'));w.state.scene=5;w.state.x=w.scene.arrive[0]+.5;w.state.y=w.scene.arrive[1]+.5;assert.ok(dropPhysical(w));const saved=w.save(),other=setup();other.restore(saved);assert.equal(physicalState(other.state).held,null);const dropped=physicalObjects(other).find(o=>o.physicalRole==='dropped');assert.ok(dropped);act(other,dropped);assert.equal(other.state.physicalLore.held,e.id);assert.equal(other.state.physicalLore.bag.filter(x=>x===e.id).length,1);assert.ok(!other.objects().some(o=>o.physicalRole==='dropped'));});
test('wrong piece, empty hands and distant actions never consume or install an object',()=>{const w=setup();act(w,site(w,PHYSICAL_LORE[0].id,'source'));const target=site(w,PHYSICAL_LORE[1].id,'device');act(w,target);assert.deepEqual(w.state.physicalLore.installed,[]);assert.equal(w.state.physicalLore.held,PHYSICAL_LORE[0].id);w.state.x+=10;interactPhysical(w,target);assert.deepEqual(w.state.physicalLore.installed,[]);assert.equal(carryPhysical(w,'missing'),false);});
test('all five mechanical actions solve; each reward is once-only across a save and advances actual skill progression',()=>{const w=setup();const questFlags=JSON.stringify(w.state.flags);let total=availablePoints(w.state,0);for(const e of PHYSICAL_LORE){solve(w,e);const reward=site(w,e.id,'reward');act(w,reward);const gold=w.state.gold,tonic=w.state.items.tonic,points=availablePoints(w.state,0);act(w,reward);assert.equal(w.state.items.tonic,tonic);assert.equal(w.state.gold,gold);assert.equal(availablePoints(w.state,0),points);if(e.chapter>=2){assert.equal(points,total+1);total=points;}const other=setup();other.restore(w.save());assert.ok(other.state.physicalLore.claimed.includes(e.id));}assert.equal(w.state.physicalLore.claimed.length,24);assert.equal(w.state.physicalLore.growthPoints[0],23);assert.equal(w.state.heroes[0].ap.earth,23*12);assert.equal(JSON.stringify(w.state.flags),questFlags);});
test('growth and silence use gameplay time and survive a mid-action save',()=>{const w=setup(),e=PHYSICAL_LORE.find(e=>e.mode==='listen');collect(w,e);act(w,site(w,e.id,'device'));assert.ok(!w.state.physicalLore.completed.includes(e.id));w.state.mode='dialog';tickPhysical(w,10);assert.equal(w.state.physicalLore.clocks[e.id],0);w.state.mode='field';for(let n=0;n<10;n++)tickPhysical(w,.1);const other=setup();other.restore(w.save());for(let n=0;n<8;n++)tickPhysical(other,.1);act(other,site(other,e.id,'device'));assert.ok(other.state.physicalLore.completed.includes(e.id));});
test('earned opening and future chapter visibility remain intact',()=>{const w=new World(data);const a=physicalBindings(w);assert.ok(a.every(o=>!w.available(o)));w.state.story.firstCore=true;assert.ok(a.filter(o=>w.available(o)).every(o=>PHYSICAL_LORE.find(e=>e.id===o.physicalId).chapter===1));assert.equal(w.state.items.tonic,0);assert.deepEqual(w.state.cores,[]);});
test('portable light reveals a real distant hiding place only while the tool is held',()=>{const w=setup(),e=PHYSICAL_LORE.find(e=>e.id==='brake-lantern');act(w,site(w,e.id,'source'));const cache={type:'secret',exploreId:'light-check',hidden:true,xy:[Math.floor(w.state.x)+4,Math.floor(w.state.y)],physicalLocation:w.state.scene};assert.ok(w.available(cache));w.state.physicalLore.held=null;assert.ok(!w.available(cache));});
test('restored gate crossing moves the crew between the actual source and receiver rooms',()=>{const w=setup(),e=PHYSICAL_LORE.find(e=>e.id==='road-wedge');solve(w,e);const source=site(w,e.id,'source'),target=site(w,e.id,'device');act(w,target);assert.equal(w.state.scene,source.physicalLocation);const crossing=w.objects().find(o=>o.physicalId===e.id&&o.physicalRole==='crossing');assert.ok(crossing);act(w,crossing);assert.equal(w.state.scene,target.physicalLocation);});
test('removed artifacts leave inspectable maker marks without granting progression or duplicating an item',()=>{const w=setup();for(const e of PHYSICAL_LORE){const source=site(w,e.id,'source');act(w,source);const trace=physicalObjects(w).find(o=>o.physicalRole==='trace'&&o.physicalId===e.id);assert.ok(trace);assert.deepEqual(trace.xy,source.xy);assert.equal(trace.physicalLocation,source.physicalLocation);const before=JSON.stringify(w.state);act(w,trace);assert.equal(JSON.stringify(w.state),before);assert.ok(!w.objects().some(o=>o.physicalRole==='source'&&o.physicalId===e.id));const restored=setup();restored.restore(w.save());assert.ok(physicalObjects(restored).some(o=>o.physicalRole==='trace'&&o.physicalId===e.id));w.state.chapter=e.chapter-1;assert.equal(w.available(trace),false);w.state.chapter=24;}});
